/**
 * Cache LRU (least recently used) com capacidade fixa.
 *
 * - `get(key)` e `set(key, value)` marcam a chave como a mais recentemente usada.
 * - `has(key)` e `peek(key)` NÃO alteram a ordem de uso.
 * - Ao inserir uma chave nova com o cache cheio, a chave usada há mais tempo é
 *   removida e `onEvict(key, value)` é chamado (apenas para remoções por
 *   capacidade; não para `delete`, `clear` ou atualização de valor).
 */
export class LRUCache {
  #map = new Map(); // ordem de iteração: menos -> mais recentemente usada
  #capacity;
  #onEvict;

  constructor(capacity, { onEvict } = {}) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError('capacity must be a positive integer');
    }
    this.#capacity = capacity;
    this.#onEvict = onEvict;
  }

  get size() {
    return this.#map.size;
  }

  get capacity() {
    return this.#capacity;
  }

  has(key) {
    return this.#map.has(key);
  }

  peek(key) {
    return this.#map.get(key);
  }

  get(key) {
    if (!this.#map.has(key)) return undefined;
    const value = this.#map.get(key);
    this.#map.delete(key);
    this.#map.set(key, value);
    return value;
  }

  set(key, value) {
    if (this.#map.has(key)) {
      this.#map.delete(key);
      this.#map.set(key, value);
      return this;
    }
    if (this.#map.size >= this.#capacity) {
      const [oldestKey, oldestValue] = this.#map.entries().next().value;
      this.#map.delete(oldestKey);
      this.#onEvict?.(oldestKey, oldestValue);
    }
    this.#map.set(key, value);
    return this;
  }

  delete(key) {
    return this.#map.delete(key);
  }

  clear() {
    this.#map.clear();
  }

  /** Chaves da menos para a mais recentemente usada. */
  keys() {
    return [...this.#map.keys()];
  }
}

